526	// buildChainRestoredStore streams a validated head-plus-rings chain into a
527	// fresh wal.log in the staging directory, applying the artifacts in chain
528	// order (each ring overriding the one before) so the result is exactly the
529	// terminal state at the chain tip. It streams one entry at a time and keeps
530	// no keyspace in memory.
531	//
532	// Frames are re-sequenced densely in application order: a key's own frames
533	// are encountered head-before-ring and in ring order, so its per-key sequence
534	// keeps increasing; replay therefore links the same terminal the chain
535	// computes. The snapshot count at the tip is appended as the closing meta,
536	// the same compacted-log shape buildRestoredStore writes. Nothing is
537	// installed until this whole step succeeds.
538	func buildChainRestoredStore(stage, backupDir string, art artifactInfo) error {
539		wf, err := os.OpenFile(filepath.Join(stage, walName), os.O_RDWR|os.O_CREATE|os.O_EXCL, 0o600)
540		if err != nil {
541			return err
542		}
543		fail := func(err error) error {
544			wf.Close()
545			return err
546		}
547		l := &walWriter{f: wf, w: bufio.NewWriter(wf)}
548		var seq uint64
549	
550		apply := func(flag byte, key string, value []byte, _ uint64) error {
551			seq++
552			if flag == ckptFlagPut {
553				return l.encodeFrameSeq(opPutSeq, key, seq, value)
554			}
555			return l.encodeFrameSeq(opDeleteSeq, key, seq, nil)
556		}
557	
558		if err := streamHeadSegments(backupDir, art.head, apply); err != nil {
559			return fail(err)
560		}
561		prevWM := art.head.watermark
562		prevLink := art.head.crc
563		for idx := uint32(1); idx <= art.ringCount; idx++ {
564			f, oerr := os.Open(filepath.Join(backupDir, ringName(idx)))
565			if oerr != nil {
566				return fail(oerr)
567			}
568			sum, serr := scanRing(f, ringExpect{
569				index:    idx,
570				prevLink: prevLink,
571				startWM:  prevWM,
572			}, apply)
573			f.Close()
574			if serr != nil {
575				return fail(serr)
576			}
577			prevWM = sum.endWM
578			prevLink = sum.fileCRC
579		}
580	
581		if art.snaps > 0 {
582			var v [metaValueSize]byte
583			binary.LittleEndian.PutUint64(v[:], art.snaps)
584			if err := l.encodeFrame(opMeta, "", v[:]); err != nil {
585				return fail(err)
586			}
587		}
588		if err := l.w.Flush(); err != nil {
589			return fail(err)
590		}
591		if err := wf.Sync(); err != nil {
592			return fail(err)
593		}
594		if err := wf.Close(); err != nil {
595			return err
596		}
597		return syncDirectory(stage)
598	}
599	
600	// presentSetAtTip streams the whole validated chain and returns the set of
601	// keys present at its tip. It is one set of live keys (bounded by live data,
602	// never by the chain length), not a copy of any value: the next incremental
603	// export needs exactly this set to tell an untouched key from one touched,
604	// deleted and then forgotten by compaction.
605	func presentSetAtTip(backupDir string, art artifactInfo) (map[string]struct{}, error) {
606		present := make(map[string]struct{})
607		add := func(flag byte, key string, _ []byte, _ uint64) error {
608			if flag == ckptFlagPut {
609				present[key] = struct{}{}
610			} else {
611				delete(present, key)
612			}
613			return nil
614		}
615		if err := streamHeadSegments(backupDir, art.head, add); err != nil {
616			return nil, err
617		}
618		prevWM := art.head.watermark
619		prevLink := art.head.crc
620		for idx := uint32(1); idx <= art.ringCount; idx++ {
621			f, err := os.Open(filepath.Join(backupDir, ringName(idx)))
622			if err != nil {
623				return nil, err
624			}
625			sum, serr := scanRing(f, ringExpect{
626				index:    idx,
627				prevLink: prevLink,
628				startWM:  prevWM,
629			}, add)
630			f.Close()
631			if serr != nil {
632				return nil, serr
633			}
634			prevWM = sum.endWM
635			prevLink = sum.fileCRC
636		}
637		return present, nil
638	}
639	
640	// ringEntryKind marks one touched key's terminal state for a new ring.
641	type ringEntryKind struct {
642		key    string
643		seq    uint64
644		delete bool
645	}
646	
647	// BackupIncremental appends one incremental ring to the backup chain in
648	// chainDir, anchored at the commit watermark current when it anchors. The
649	// chain directory must already hold a complete full backup (the chain head);
650	// writes and deletes committed after the anchor do not enter the ring, while
651	// the foreground keeps committing.
652	//
653	// The ring holds only the terminal state of keys touched between the chain
654	// tip's watermark and the anchor: later puts overwrite earlier ones, and keys
655	// deleted in the interval are recorded as tombstones and read back as misses
656	// after synthesis. Keys the compaction has forgotten entirely but the chain
657	// once held are recorded as tombstones too, so a delete is never resurrected
658	// by a later compaction of the backed-up store.
659	//
660	// The ring is streamed in bounded chunks and installed all-or-nothing under
661	// a staging name: a kill at any instant leaves the chain exactly as it was
662	// (staging debris is swept at the next export into, or Open of, the
663	// directory), and the backed-up store is never modified.
664	//
665	// The export takes the chain directory's lease before touching anything, so
666	// concurrent exports, merges and restores on the same chain directory — from
667	// this store, another store or another process — are mutually exclusive: at
668	// most one registered operation advances the chain at a time. An export that
669	// cannot take the lease fails wholesale with an error wrapping fs.ErrInvalid
670	// and leaves no partial ring; a lease left behind by a killed holder is
671	// reclaimed, never waited on.
672	//
673	// A chain directory that is missing, not a directory, incomplete or damaged
674	// (a missing ring, a broken link, a non-continuous watermark, truncation,
675	// checksum failure or unknown version), or a chain advanced concurrently
676	// during the export, rejects the whole operation with an error wrapping
677	// fs.ErrInvalid and leaves no partial ring. BackupIncremental on a closed
678	// store returns an error wrapping fs.ErrClosed.
679	func (s *Store) BackupIncremental(chainDir string) error {
680		if s.closed.Load() {
681			return errStoreClosed
682		}
683		// Serialize exports driven by one store so they can never share a staging
684		// directory or race to append the same ring index. This does not serialize
685		// with commits or reads.
686		s.backupMu.Lock()
687		defer s.backupMu.Unlock()
688		if s.closed.Load() {
689			return errStoreClosed
690		}
691		if chainDir == "" {
692			return errBadBackup
693		}
694		// Coordinate with every other operation on this chain directory, in this
695		// process or another: only the lease holder may repair debris, validate
696		// the chain and append a ring. A live holder fails the whole export; a
697		// killed holder's lease is reclaimed.
698		lease, err := acquireChainLease(chainDir)
699		if err != nil {
700			return err
701		}
702		defer lease.release()
703		// Repair or clear debris from a merge killed mid-commit before inspecting
704		// the chain.
705		sweepMergeDebris(chainDir)
706		info, err := os.Stat(chainDir)
707		if err != nil {
708			if errors.Is(err, os.ErrNotExist) {
709				return errBadBackup
710			}
711			return err
712		}
713		if !info.IsDir() {
714			return errBadBackup
715		}
716		// Clear staging debris from an export (full or incremental) killed mid-run
717		// before inspecting the chain; a manifest temp is pure debris as well.
718		for _, stage := range []string{incrStageDir, backupStageDir} {
719			if err := os.RemoveAll(filepath.Join(chainDir, stage)); err != nil {
720				return err
721			}
722		}
723		if err := os.Remove(filepath.Join(chainDir, backupManifestTmp)); err != nil &&
724			!errors.Is(err, os.ErrNotExist) {
725			return err
726		}
727	
728		art, err := validateBackupChain(chainDir)
729		if err != nil {
730			return err
731		}
732		// The chain tip's present-key set is the baseline the touched set is
733		// diffed against. Streamed from immutable artifacts, it needs no lock.
734		prevPresent, err := presentSetAtTip(chainDir, art)
735		if err != nil {
736			return err
737		}
738	
739		// Anchor at one fixed watermark. This is the only moment the export takes
740		// the write lock; entry resolution and streaming run on the immutable
741		// anchored view without it.
742		s.mu.Lock()
743		if s.closed.Load() {
744			s.mu.Unlock()
745			return errStoreClosed
746		}
747		anchor := backupAnchor{
748			view:      s.current.Load(),
749			watermark: s.nextSeq,
750			snaps:     s.snapshots.Load(),
751		}
752		s.mu.Unlock()
753	
754		startWM := art.endWM
755		// The anchor must be a continuation of the chain: a watermark or snapshot
756		// count behind the tip means this store cannot extend that chain, so the
757		// export is rejected wholesale before any ring file is staged.
758		if anchor.watermark < startWM || anchor.snaps < art.snaps {
759			return errBadBackup
760		}
761		touched := collectTouchedKeys(anchor.view, prevPresent, startWM, anchor.watermark)
762		// Every entry must be orderable strictly inside (startWM, endWM]: a
763		// tombstone synthesized for a forgotten key is stamped at the anchor, so
764		// when the anchor did not advance past the tip this store cannot
765		// represent that delete on the chain at all. Reject the export wholesale
766		// rather than write a ring no validation would accept.
767		for _, e := range touched {
768			if e.seq <= startWM || e.seq > anchor.watermark {
769				return errBadBackup
770			}
771		}
772	
773		index := art.ringCount + 1
774		return writeIncrementalRing(chainDir, ringHeader{
775			index:    index,
776			prevLink: art.tipCRC,
777			startWM:  startWM,
778			endWM:    anchor.watermark,
779			snaps:    anchor.snaps,
780		}, anchor, touched)
781	}
782	
783	// ringHeader carries the fixed fields of a ring being written.
784	type ringHeader struct {
785		index    uint32
786		prevLink uint32
787		startWM  uint64
788		endWM    uint64
789		snaps    uint64
790	}
791	
792	// collectTouchedKeys diffs the anchored view against the present-key set the
793	// chain held at startWM and returns the touched keys' terminal state, sorted
794	// by key. A key present in the chain but absent from the view was deleted and
795	// forgotten by compaction; it still enters the ring as a tombstone, stamped
796	// at the anchor watermark.
797	func collectTouchedKeys(v *view, prevPresent map[string]struct{}, startWM, endWM uint64) []ringEntryKind {
798		var touched []ringEntryKind
799		seen := make(map[string]struct{}, len(prevPresent))
800		v.rangeEach(func(k string, n *node) bool {
801			seen[k] = struct{}{}
802			_, was := prevPresent[k]
803			if n.present {
804				if !was || n.seq > startWM {
805					touched = append(touched, ringEntryKind{key: k, seq: n.seq})
806				}
807			} else if was {
808				touched = append(touched, ringEntryKind{key: k, seq: n.seq, delete: true})
809			}
810			return true
811		})
812		// Keys the chain knew but the view no longer even mentions: deleted and
813		// dropped by a compaction. Stamp the tombstone at the anchor.
814		for k := range prevPresent {
815			if _, ok := seen[k]; ok {
816				continue
817			}
818			touched = append(touched, ringEntryKind{key: k, seq: endWM, delete: true})
819		}
820		sort.Slice(touched, func(i, j int) bool { return touched[i].key < touched[j].key })
821		return touched
822	}
823	
824	// writeIncrementalRing streams one ring in bounded chunks, fully syncs it in
825	// the staging directory and links it into place atomically (link fails
826	// rather than overwrite when another export advanced the chain). The chain
827	// directory is forced afterwards.
828	func writeIncrementalRing(chainDir string, hdr ringHeader, anchor backupAnchor, touched []ringEntryKind) error {
829		final := ringName(hdr.index)
830	
831		// Refuse to build before staging anything if another ring of this index
832		// already exists: a concurrent export appended first.
833		if _, err := os.Stat(filepath.Join(chainDir, final)); err == nil {
834			return errBadBackup
835		} else if !errors.Is(err, os.ErrNotExist) {
836			return err
837		}
838	
839		stage := filepath.Join(chainDir, incrStageDir)
840		if err := os.MkdirAll(stage, 0o700); err != nil {
841			if errors.Is(err, os.ErrExist) {
842				// A non-directory entry occupies the staging name: foreign debris,
843				// never a usable chain.
844				return errBadBackup
845			}
846			return err
847		}
848		tmpPath := filepath.Join(stage, final)
849		cleanup := func() { os.RemoveAll(stage) }
850	
851		tmp, err := os.OpenFile(tmpPath, os.O_RDWR|os.O_CREATE|os.O_EXCL, 0o600)
852		if err != nil {
853			if errors.Is(err, os.ErrExist) {
854				// Another export is already staging this ring: this store cannot
855				// also append it.
856				cleanup()
857				return errBadBackup
858			}
859			cleanup()
860			return err
861		}
862		fail := func(err error) error {
863			tmp.Close()
864			cleanup()
865			return err
866		}
867	
868		w := bufio.NewWriter(tmp)
869		hf := crc32.NewIEEE()
870		// write bytes to the ring, advancing the whole-file CRC for every byte.
871		write := func(b []byte) error {
872			if _, err := w.Write(b); err != nil {
873				return err
874			}
875			hf.Write(b)
876			return nil
877		}
878	
879		segCount := uint32(0)
880		if len(touched) > 0 {
881			segCount = uint32((len(touched) + backupEntriesPerSegment - 1) / backupEntriesPerSegment)
882		}
883	
884		head := make([]byte, incrRingHeaderSize)
885		binary.LittleEndian.PutUint32(head[0:4], backupMagic)
886		binary.LittleEndian.PutUint32(head[4:8], backupVersion)
887		binary.LittleEndian.PutUint32(head[8:12], hdr.index)
888		binary.LittleEndian.PutUint32(head[12:16], hdr.prevLink)
889		binary.LittleEndian.PutUint64(head[16:24], hdr.startWM)
890		binary.LittleEndian.PutUint64(head[24:32], hdr.endWM)
891		binary.LittleEndian.PutUint64(head[32:40], hdr.snaps)
892		binary.LittleEndian.PutUint32(head[40:44], segCount)
893		if err := write(head); err != nil {
894			return fail(err)
895		}
896	
897		ehdr := make([]byte, checkpointEntrySize)
898		var segChain uint32
899		var cumulative uint64
900		for seg := uint32(0); seg < segCount; seg++ {
901			start := int(seg) * backupEntriesPerSegment
902			stop := start + backupEntriesPerSegment
903			if stop > len(touched) {
904				stop = len(touched)
905			}
906			chunk := touched[start:stop]
907	
908			hs := crc32.NewIEEE()
909			sh := make([]byte, incrSegHeaderSize)
910			binary.LittleEndian.PutUint32(sh[0:4], backupMagic)
911			binary.LittleEndian.PutUint64(sh[4:12], hdr.startWM)
912			binary.LittleEndian.PutUint64(sh[12:20], hdr.endWM)
913			binary.LittleEndian.PutUint32(sh[20:24], hdr.index)
914			binary.LittleEndian.PutUint32(sh[24:28], seg)
915			// cumulative is filled after the chunk is encoded; entries cannot be
916			// dropped, so the count equals the chunk length.
917			cumulative += uint64(len(chunk))
918			binary.LittleEndian.PutUint32(sh[28:32], uint32(len(chunk)))
919			binary.LittleEndian.PutUint64(sh[32:40], cumulative)
920			if err := write(sh); err != nil {
921				return fail(err)
922			}
923			hs.Write(sh)
924	
925			writeEntry := func(flag byte, key string, value []byte, seq uint64) error {
926				if len(key) > maxRecord || len(value) > maxRecord {
927					return errors.New("snapshot: incremental entry too large")
928				}
929				if flag == ckptFlagPut {
930					ehdr[0] = ckptFlagPut
931				} else {
932					ehdr[0] = ckptFlagDelete
933				}
934				binary.LittleEndian.PutUint32(ehdr[1:5], uint32(len(key)))
935				binary.LittleEndian.PutUint32(ehdr[5:9], uint32(len(value)))
936				binary.LittleEndian.PutUint64(ehdr[9:17], seq)
937				if err := write(ehdr); err != nil {
938					return err
939				}
940				hs.Write(ehdr)
941				if _, err := io.WriteString(w, key); err != nil {
942					return err
943				}
944				hf.Write([]byte(key))
945				hs.Write([]byte(key))
946				if len(value) > 0 {
947					if err := write(value); err != nil {
948						return err
949					}
950					hs.Write(value)
951				}
952				return nil
953			}
954	
955			for _, e := range chunk {
956				if e.delete {
957					if err := writeEntry(ckptFlagDelete, e.key, nil, e.seq); err != nil {
958						return fail(err)
959					}
960				} else {
961					n := anchor.view.lookup(e.key)
962					if n == nil || !n.present || n.seq != e.seq {
963						return fail(errBadBackup)
964					}
965					if err := writeEntry(ckptFlagPut, e.key, cloneBytes(n.value), e.seq); err != nil {
966						return fail(err)
967					}
968				}
969			}
970	
971			var sc [crcSize]byte
972			binary.LittleEndian.PutUint32(sc[:], hs.Sum32())
973			if err := write(sc[:]); err != nil {
974				return fail(err)
975			}
976			segChain = crc32.Update(segChain, crc32.IEEETable, sc[:])
977		}
978	
979		foot := make([]byte, incrFooterSize)
980		binary.LittleEndian.PutUint64(foot[0:8], cumulative)
981		binary.LittleEndian.PutUint32(foot[8:12], segCount)
982		binary.LittleEndian.PutUint32(foot[12:16], segChain)
983		if err := write(foot); err != nil {
984			return fail(err)
985		}
986		var fc [crcSize]byte
987		binary.LittleEndian.PutUint32(fc[:], hf.Sum32())
988		// Flush every buffered byte before appending the terminal CRC: writing it
989		// through the raw file while the bufio writer still held content would
990		// place the CRC at offset 0 and the buffered body after it.
991		if err := w.Flush(); err != nil {
992			return fail(err)
993		}
994		if _, err := tmp.Write(fc[:]); err != nil {
995			return fail(err)
996		}
997		if err := tmp.Sync(); err != nil {
998			return fail(err)
999		}
1000		if err := tmp.Close(); err != nil {
1001			cleanup()
1002			return err
1003		}
1004	
1005		// Promote with link(2): it never overwrites, so a concurrent export cannot
1006		// be clobbered, and the ring appears whole or not at all.
1007		if err := os.Link(tmpPath, filepath.Join(chainDir, final)); err != nil {
1008			if errors.Is(err, os.ErrExist) {
1009				cleanup()
1010				return errBadBackup
1011			}
1012			cleanup()
1013			return err
1014		}
1015		if err := syncDirectory(chainDir); err != nil {
1016			return err
1017		}
1018		cleanup()
1019		return syncDirectory(chainDir)
1020	}
1021

