20	// chain: their entries, watermarks and snapshot counts are unchanged, but
21	// they are re-linked and renumbered from 1 behind the new head, so the merged
22	// chain still validates as one whole — dense ring numbering, continuous
23	// watermarks, unbroken content-CRC links — and later BackupIncremental rings
24	// append to it exactly as before.
25	//
26	// The merge is fully streamed: the new head is built by a k-way merge over
27	// the old head segments and the first n rings (all key-sorted streams), and
28	// each surviving ring is re-encoded entry by entry. One bounded chunk of
29	// entries is resident at a time; the keyspace is never copied into memory
30	// wholesale before hitting disk.
31	//
32	// The new chain is assembled in a sibling staging directory
33	// ("<chain>.merge-new-*") next to the chain directory and validated as a
34	// whole chain before anything is committed. The commit swaps directories:
35	// the old chain is renamed aside ("<chain>.merge-old-*"), the staged chain is
36	// renamed onto the chain path, and only then is the old chain deleted. A kill
37	// at any instant therefore leaves either the old chain or the complete new
38	// chain at the chain path — at worst a staging or trash sibling remains, and
39	// a kill between the two renames is repaired by moving the whole old chain
40	// back. The debris is swept at the next merge, backup or incremental export
41	// into that directory, or the next open of a related directory.
42	//
43	// MergeChain never touches the backed-up store: it reads only chain
44	// artifacts, so writes, batch commits, snapshot open/close, cursor paging,
45	// checkpoints, compactions and lock-free reads proceed while it runs. It is
46	// serialized with incremental exports on the same store (and re-validates the
47	// chain tip before committing, so a chain advanced concurrently by another
48	// exporter rejects the merge wholesale rather than being clobbered by it).
49	const (
50		mergeStagePrefix = ".merge-new-"
51		mergeTrashPrefix = ".merge-old-"
52	)
53	
54	// errMergeAbort stops a stream goroutine when the merge that owns it fails;
55	// it is internal flow control and never escapes to a caller.
56	var errMergeAbort = errors.New("snapshot: merge stream aborted")
57	
58	// MergeChain merges the head of the backup chain in chainDir with its first
59	// rings incremental rings into one new full head and deletes the absorbed
60	// rings. The merged chain restores to exactly the state and cumulative
61	// snapshot count the original chain captured, keeps the remaining rings
62	// (renumbered from 1 behind the new head), passes the same whole-chain
63	// validation Restore performs, and accepts further BackupIncremental rings.
64	//
65	// The merge streams every artifact in bounded chunks and never holds the
66	// whole keyspace in memory. It runs entirely on the chain directory: the
67	// backed-up store is never modified, and live writes, batch commits,
68	// snapshots, cursors, checkpoints, compactions and reads proceed while it
69	// runs. The new chain is staged as a sibling directory, validated as a whole,
70	// and swapped into place so a kill at any instant leaves either the old chain
71	// or the complete new chain; leftover staging or trash siblings are swept at
72	// the next merge, backup or export into that directory or the next open of a
73	// related directory.
74	//
75	// The merge takes the chain directory's lease before touching anything, so
76	// concurrent exports, merges and restores on the same chain directory — from
77	// this store, another store or another process — are mutually exclusive: at
78	// most one registered operation advances the chain at a time. A merge that
79	// cannot take the lease fails wholesale with an error wrapping fs.ErrInvalid
80	// and leaves the chain exactly as it was; a lease left behind by a killed
81	// holder is reclaimed, never waited on.
82	//
83	// A ring count below one or beyond the chain's ring count, a chain directory
84	// that is missing, not a directory, missing its head, or itself damaged (a
85	// missing ring, a broken link, a non-continuous watermark, truncation, a
86	// checksum failure or an unknown version), or a chain advanced concurrently
87	// during the merge, rejects the whole operation with an error wrapping
88	// fs.ErrInvalid and leaves the chain exactly as it was. MergeChain on a
89	// closed store returns an error wrapping fs.ErrClosed.
90	func (s *Store) MergeChain(chainDir string, rings int) error {
91		if s.closed.Load() {
92			return errStoreClosed
93		}
94		// Serialize with incremental exports driven by this store so a merge and
95		// an export never race to reshape the same chain. This lock is
96		// independent of mu: it is held across the merge's disk I/O and never
97		// blocks commits or lock-free reads.
98		s.backupMu.Lock()
99		defer s.backupMu.Unlock()
100		if s.closed.Load() {
101			return errStoreClosed
102		}
103		if chainDir == "" || rings < 1 {
104			return errBadBackup
105		}
106		// Coordinate with every other operation on this chain directory, in this
107		// process or another: only the lease holder may repair debris, validate
108		// the chain and swap a merged chain into place. A live holder fails the
109		// whole merge; a killed holder's lease is reclaimed.
110		lease, err := acquireChainLease(chainDir)
111		if err != nil {
112			return err
113		}
114		defer lease.release()
115		// Repair or clear debris from a merge killed mid-commit before inspecting
116		// the chain, exactly as the next backup or open of the directory would.
117		sweepMergeDebris(chainDir)
118		info, err := os.Stat(chainDir)
119		if err != nil {
120			if errors.Is(err, os.ErrNotExist) {
121				return errBadBackup
122			}
123			return err
124		}
125		if !info.IsDir() {
126			return errBadBackup
127		}
128		// Clear staging debris from an export (full or incremental) killed
129		// mid-run; a manifest temp is pure debris as well.
130		for _, stage := range []string{incrStageDir, backupStageDir} {
131			if err := os.RemoveAll(filepath.Join(chainDir, stage)); err != nil {
132				return err
133			}
134		}
135		if err := os.Remove(filepath.Join(chainDir, backupManifestTmp)); err != nil &&
136			!errors.Is(err, os.ErrNotExist) {
137			return err
138		}
139	
140		art, err := validateBackupChain(chainDir)
141		if err != nil {
142			return err
143		}
144		if uint64(rings) > uint64(art.ringCount) {
145			return errBadBackup
146		}
147		n := rings
148	
149		// Stage the whole merged chain as a sibling of the chain directory so the
150		// final swap is a same-filesystem rename. The chain directory itself is
151		// not touched until the commit.
152		parent := filepath.Dir(chainDir)
153		base := filepath.Base(chainDir)
154		stage, err := os.MkdirTemp(parent, base+mergeStagePrefix)
155		if err != nil {
156			return err
157		}
158		committed := false
159		defer func() {
160			if !committed {
161				os.RemoveAll(stage)
162			}
163		}()
164	
165		// The new head covers the chain through ring n: its export watermark and
166		// cumulative snapshot count are exactly that ring's.
167		tip := art.ringSums[n-1]
168		anchor := backupAnchor{watermark: tip.endWM, snaps: tip.snaps}
169		segs, total, err := mergeChainHead(chainDir, stage, art, n, anchor)
170		if err != nil {
171			return err
172		}
173		if err := writeManifest(stage, stage, anchor, total, segs); err != nil {
174			return err
175		}
176		newHead, err := loadBackupManifest(stage)
177		if err != nil {
178			return err
179		}
180	
181		// Re-encode each surviving ring under its new 1-based index, linked to
182		// the artifact before it in the merged chain. Entries, watermarks and
183		// snapshot counts are carried over unchanged.
184		prevLink := newHead.crc
185		for j := n + 1; j <= int(art.ringCount); j++ {
186			old := art.ringSums[j-1]
187			prev := art.ringSums[j-2]
188			hdr := ringHeader{
189				index:    uint32(j - n),
190				prevLink: prevLink,
191				startWM:  prev.endWM,
192				endWM:    old.endWM,
193				snaps:    old.snaps,
194			}
195			exp := ringExpect{
196				index:    uint32(j),
197				prevLink: prev.fileCRC,
198				startWM:  prev.endWM,
199			}
200			prevLink, err = renumberRing(chainDir, stage, exp, hdr, old.segCount, old.total)
201			if err != nil {
202				return err
203			}
204		}
205	
206		// The staged chain must pass the same whole-chain validation Restore
207		// performs, and it must reach the same tip the original chain reached.
208		newArt, err := validateBackupChain(stage)
209		if err != nil {
210			return err
211		}
212		if newArt.ringCount != art.ringCount-uint32(n) ||
213			newArt.endWM != art.endWM || newArt.snaps != art.snaps {
214			return errBadBackup
215		}
216	
217		// Refuse to commit over a chain that moved since it was validated (an
218		// export or merge driven by another store): the merge is rejected
219		// wholesale and the chain keeps its newer shape.
220		again, err := validateBackupChain(chainDir)
221		if err != nil {
222			return err
223		}
224		if again.head.crc != art.head.crc || again.ringCount != art.ringCount ||
225			again.tipCRC != art.tipCRC || again.endWM != art.endWM ||
226			again.snaps != art.snaps {
227			return errBadBackup
228		}
229	
230		// Commit: move the old chain aside, move the staged chain onto the chain
231		// path, then delete the old chain. A kill before the first rename leaves
232		// the old chain; a kill between the renames leaves the whole old chain in
233		// the trash sibling (swept back into place next time); a kill after the
234		// second rename leaves the complete new chain.
235		trash, err := os.MkdirTemp(parent, base+mergeTrashPrefix)
236		if err != nil {
237			return err
238		}
239		if err := os.Remove(trash); err != nil {
240			return err
241		}
242		if err := os.Rename(chainDir, trash); err != nil {
243			return err
244		}
245		if err := os.Rename(stage, chainDir); err != nil {
246			// Best-effort rollback: the old chain is whole at trash.
247			if rb := os.Rename(trash, chainDir); rb == nil {
248				_ = syncDirectory(parent)
249			}
250			return err
251		}
252		committed = true
253		if err := syncDirectory(parent); err != nil {
254			return err
255		}
256		if err := os.RemoveAll(trash); err != nil {
257			return err
258		}
259		return syncDirectory(parent)
260	}
261	
262	// streamItem carries one entry (or a terminal error) from a chain artifact
263	// being streamed by a goroutine.
264	type streamItem struct {
265		flag  byte
266		key   string
267		value []byte
268		seq   uint64
269		err   error
270	}
271	
272	// mergeStream is the pull side of one streamed chain artifact. The goroutine
273	// validates as it streams, so a consumed stream is a validated artifact.
274	type mergeStream struct {
275		ch   chan streamItem
276		stop chan struct{}
277		cur  streamItem
278		has  bool
279		err  error
280	}
281	
282	// send hands one item to the consumer; it reports errMergeAbort when the
283	// merge has been abandoned, which unwinds the streaming goroutine.
284	func (ms *mergeStream) send(it streamItem) error {
285		select {
286		case ms.ch <- it:
287			return nil
288		case <-ms.stop:
289			return errMergeAbort
290		}
291	}
292	
293	// next advances to the next entry; afterwards has reports whether cur holds
294	// an entry and err holds the stream's terminal error, if any.
295	func (ms *mergeStream) next() {
296		it, ok := <-ms.ch
297		if !ok {
298			ms.has = false
299			return
300		}
301		if it.err != nil {
302			ms.err = it.err
303			ms.has = false
304			return
305		}
306		ms.cur = it
307		ms.has = true
308	}
309	
310	// abort stops the streaming goroutine and lets it exit; it is safe to call
311	// after the stream has already finished.
312	func (ms *mergeStream) abort() {
313		select {
314		case <-ms.stop:
315		default:
316			close(ms.stop)
317		}
318	}
319	
320	// startHeadStream streams the head's segments in order, validating as they
321	// are read.
322	func startHeadStream(dir string, head manifestInfo) *mergeStream {
323		ms := &mergeStream{ch: make(chan streamItem, 1), stop: make(chan struct{})}
324		go func() {
325			defer close(ms.ch)
326			err := streamHeadSegments(dir, head, func(flag byte, key string, value []byte, seq uint64) error {
327				return ms.send(streamItem{flag: flag, key: key, value: value, seq: seq})
328			})
329			if err != nil {
330				ms.send(streamItem{err: err})
331			}
332		}()
333		return ms
334	}
335	
336	// startRingStream streams one ring's entries in order, validating the whole
337	// ring and its linkage against exp as it is read.
338	func startRingStream(dir string, exp ringExpect) *mergeStream {
339		ms := &mergeStream{ch: make(chan streamItem, 1), stop: make(chan struct{})}
340		go func() {
341			defer close(ms.ch)
342			f, err := os.Open(filepath.Join(dir, ringName(exp.index)))
343			if err != nil {
344				ms.send(streamItem{err: err})
345				return
346			}
347			defer f.Close()
348			_, err = scanRing(f, exp, func(flag byte, key string, value []byte, seq uint64) error {
349				return ms.send(streamItem{flag: flag, key: key, value: value, seq: seq})
350			})
351			if err != nil {
352				ms.send(streamItem{err: err})
353			}
354		}()
355		return ms
356	}
357	
358	// mergeChainHead builds the merged head's segments in stage by k-way merging
359	// the old head with the first n rings, all strictly key-ordered streams. For
360	// a key present in several streams the latest ring wins (rings in order, then
361	// the head); a winning tombstone drops the key, so deletes covered by the
362	// merged rings read back as misses. Only one chunk of entries is resident at
363	// a time. It returns the manifest segment records and the total entry count.
364	func mergeChainHead(chainDir, stage string, art artifactInfo, n int, anchor backupAnchor) ([]manifestSegment, uint64, error) {
365		streams := make([]*mergeStream, 0, n+1)
366		streams = append(streams, startHeadStream(chainDir, art.head))
367		prevLink := art.head.crc
368		prevWM := art.head.watermark
369		for j := 1; j <= n; j++ {
370			streams = append(streams, startRingStream(chainDir, ringExpect{
371				index:    uint32(j),
372				prevLink: prevLink,
373				startWM:  prevWM,
374			}))
375			sum := art.ringSums[j-1]
376			prevLink, prevWM = sum.fileCRC, sum.endWM
377		}
378		defer func() {
379			for _, s := range streams {
380				s.abort()
381			}
382		}()
383		for _, s := range streams {
384			s.next()
385		}
386	
387		var segs []manifestSegment
388		var total uint64
389		var segIdx uint32
390		chunk := make([]backupEntry, 0, backupEntriesPerSegment)
391		flush := func() error {
392			if len(chunk) == 0 {
393				return nil
394			}
395			cumulative := total + uint64(len(chunk))
396			crc, err := writeSegment(stage, segIdx, anchor, cumulative, chunk)
397			if err != nil {
398				return err
399			}
400			segs = append(segs, manifestSegment{
401				index:      segIdx,
402				count:      uint32(len(chunk)),
403				cumulative: cumulative,
404				crc:        crc,
405			})
406			total = cumulative
407			segIdx++
408			chunk = chunk[:0]
409			return nil
410		}
411	
412		for {
413			// The smallest key still pending across all streams is next; among
414			// the streams holding it, the latest ring (highest stream index)
415			// holds its terminal state.
416			winner := -1
417			var min string
418			for i, s := range streams {
419				if s.has && (winner < 0 || s.cur.key < min) {
420					min, winner = s.cur.key, i
421				}
422			}
423			if winner < 0 {
424				break
425			}
426			for i, s := range streams {
427				if s.has && s.cur.key == min {
428					winner = i
429				}
430			}
431			if w := streams[winner]; w.cur.flag == ckptFlagPut {
432				chunk = append(chunk, backupEntry{
433					key:     w.cur.key,
434					value:   w.cur.value,
435					seq:     w.cur.seq,
436					present: true,
437				})
438				if len(chunk) == backupEntriesPerSegment {
439					if err := flush(); err != nil {
440						return nil, 0, err
441					}
442				}
443			}
444			for _, s := range streams {
445				if s.has && s.cur.key == min {
446					s.next()
447				}
448			}
449			for _, s := range streams {
450				if s.err != nil {
451					return nil, 0, s.err
452				}
453			}
454		}
455		for _, s := range streams {
456			if s.err != nil {
457				return nil, 0, s.err
458			}
459		}
460		if err := flush(); err != nil {
461			return nil, 0, err
462		}
463		return segs, total, nil
464	}
465	
466	// renumberRing streams the old ring identified by exp out of chainDir,
467	// validates it, and re-encodes it in stage under hdr's new index and link.
468	// The entries, watermarks, snapshot count, segmenting and entry count are
469	// carried over unchanged from the validated ring summary. It returns the new
470	// ring's terminal file CRC, the link the next ring must name.
471	func renumberRing(chainDir, stage string, exp ringExpect, hdr ringHeader, segCount uint32, total uint64) (uint32, error) {
472		src := startRingStream(chainDir, exp)
473		defer src.abort()
474		src.next()
475		crc, err := writeMergedRing(filepath.Join(stage, ringName(hdr.index)), hdr, segCount, total, src)
476		if err != nil {
477			return 0, err
478		}
479		if src.err != nil {
480			return 0, src.err
481		}
482		if src.has {
483			return 0, errBadBackup // more entries than the validated ring declared
484		}
485		return crc, nil
486	}
487	
488	// writeMergedRing streams one ring file at path, pulling exactly total
489	// entries (chunked into segCount segments) from src. The layout is the ring
490	// format writeIncrementalRing emits; only the entry source differs. The file
491	// is fully synced before its CRC is returned.
492	func writeMergedRing(path string, hdr ringHeader, segCount uint32, total uint64, src *mergeStream) (uint32, error) {
493		tmp, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE|os.O_EXCL, 0o600)
494		if err != nil {
495			return 0, err
496		}
497		fail := func(err error) (uint32, error) {
498			tmp.Close()
499			os.Remove(path)
500			return 0, err
501		}
502	
503		w := bufio.NewWriter(tmp)
504		hf := crc32.NewIEEE()
505		write := func(b []byte) error {
506			if _, err := w.Write(b); err != nil {
507				return err
508			}
509			hf.Write(b)
510			return nil
511		}
512	
513		head := make([]byte, incrRingHeaderSize)
514		binary.LittleEndian.PutUint32(head[0:4], backupMagic)
515		binary.LittleEndian.PutUint32(head[4:8], backupVersion)
516		binary.LittleEndian.PutUint32(head[8:12], hdr.index)
517		binary.LittleEndian.PutUint32(head[12:16], hdr.prevLink)
518		binary.LittleEndian.PutUint64(head[16:24], hdr.startWM)
519		binary.LittleEndian.PutUint64(head[24:32], hdr.endWM)
520		binary.LittleEndian.PutUint64(head[32:40], hdr.snaps)
521		binary.LittleEndian.PutUint32(head[40:44], segCount)
522		if err := write(head); err != nil {
523			return fail(err)
524		}
525	
526		ehdr := make([]byte, checkpointEntrySize)
527		var segChain uint32
528		var cumulative uint64
529		remaining := total
530		for seg := uint32(0); seg < segCount; seg++ {
531			size := uint64(backupEntriesPerSegment)
532			if remaining < size {
533				size = remaining
534			}
535			remaining -= size
536	
537			hs := crc32.NewIEEE()
538			sh := make([]byte, incrSegHeaderSize)
539			binary.LittleEndian.PutUint32(sh[0:4], backupMagic)
540			binary.LittleEndian.PutUint64(sh[4:12], hdr.startWM)
541			binary.LittleEndian.PutUint64(sh[12:20], hdr.endWM)
542			binary.LittleEndian.PutUint32(sh[20:24], hdr.index)
543			binary.LittleEndian.PutUint32(sh[24:28], seg)
544			cumulative += size
545			binary.LittleEndian.PutUint32(sh[28:32], uint32(size))
546			binary.LittleEndian.PutUint64(sh[32:40], cumulative)
547			if err := write(sh); err != nil {
548				return fail(err)
549			}
550			hs.Write(sh)
551	
552			for i := uint64(0); i < size; i++ {
553				if !src.has {
554					return fail(errBadBackup) // fewer entries than the ring declared
555				}
556				it := src.cur
557				if len(it.key) > maxRecord || len(it.value) > maxRecord {
558					return fail(errBadBackup)
559				}
560				ehdr[0] = it.flag
561				binary.LittleEndian.PutUint32(ehdr[1:5], uint32(len(it.key)))
562				binary.LittleEndian.PutUint32(ehdr[5:9], uint32(len(it.value)))
563				binary.LittleEndian.PutUint64(ehdr[9:17], it.seq)
564				if err := write(ehdr); err != nil {
565					return fail(err)
566				}
567				hs.Write(ehdr)
568				if _, err := io.WriteString(w, it.key); err != nil {
569					return fail(err)
570				}
571				hf.Write([]byte(it.key))
572				hs.Write([]byte(it.key))
573				if len(it.value) > 0 {
574					if err := write(it.value); err != nil {
575						return fail(err)
576					}
577					hs.Write(it.value)
578				}
579				src.next()
580				if src.err != nil {
581					return fail(src.err)
582				}
583			}
584	
585			var sc [crcSize]byte
586			binary.LittleEndian.PutUint32(sc[:], hs.Sum32())
587			if err := write(sc[:]); err != nil {
588				return fail(err)
589			}
590			segChain = crc32.Update(segChain, crc32.IEEETable, sc[:])
591		}
592		if cumulative != total {
593			return fail(errBadBackup)
594		}
595	
596		foot := make([]byte, incrFooterSize)
597		binary.LittleEndian.PutUint64(foot[0:8], cumulative)
598		binary.LittleEndian.PutUint32(foot[8:12], segCount)
599		binary.LittleEndian.PutUint32(foot[12:16], segChain)
600		if err := write(foot); err != nil {
601			return fail(err)
602		}
603		var fc [crcSize]byte
604		binary.LittleEndian.PutUint32(fc[:], hf.Sum32())
605		// Flush every buffered byte before appending the terminal CRC, exactly as
606		// writeIncrementalRing does.
607		if err := w.Flush(); err != nil {
608			return fail(err)
609		}
610		if _, err := tmp.Write(fc[:]); err != nil {
611			return fail(err)
612		}
613		if err := tmp.Sync(); err != nil {
614			return fail(err)
615		}
616		if err := tmp.Close(); err != nil {
617			os.Remove(path)
618			return 0, err
619		}
620		return binary.LittleEndian.Uint32(fc[:]), nil
621	}
