14	// Restore loads a backup artifact produced by Store.Backup from backupDir and
15	// installs a ready-to-open store into targetDir, returning it already open.
16	// The restored directory, once reopened, is byte-for-byte the complete
17	// committed state at the export watermark: a full replay from it yields the
18	// same terminal state the backup captured, and the cumulative snapshot count
19	// is preserved exactly.
20	//
21	// The artifact is validated as one whole before anything is installed: a
22	// missing segment, a truncated segment, a checksum mismatch, an unknown format
23	// version or a manifest that disagrees with the files rejects the entire
24	// backup with an error wrapping fs.ErrInvalid, and no target is created.
25	//
26	// Installation is all-or-nothing: the new store is fully built and synced in a
27	// temporary sibling directory and only then renamed onto targetDir. A process
28	// killed at any instant leaves either the previous target or one complete
29	// store; a half-built temporary directory is swept by the next Restore or the
30	// next Open of the related directory.
31	//
32	// A backup path that does not exist or is not a directory is rejected with an
33	// error wrapping fs.ErrInvalid. A target path that already exists and is not
34	// empty (including a regular file) is rejected the same way.
35	//
36	// The restore takes the chain directory's lease before touching anything, so
37	// concurrent exports, merges and restores on the same chain directory are
38	// mutually exclusive: a restore that cannot take the lease fails wholesale
39	// with an error wrapping fs.ErrInvalid and creates no target, and a lease
40	// left behind by a killed holder is reclaimed, never waited on.
41	func Restore(backupDir, targetDir string) (*Store, error) {
42		if backupDir == "" || targetDir == "" {
43			return nil, errBadBackup
44		}
45	
46		// Coordinate with every other operation on this chain directory, in this
47		// process or another: only the lease holder may repair debris and stream
48		// the chain. A live holder fails the whole restore; a killed holder's
49		// lease is reclaimed.
50		lease, err := acquireChainLease(backupDir)
51		if err != nil {
52			return nil, err
53		}
54		defer lease.release()
55	
56		// The artifact itself must be an existing directory whose only entries are
57		// the manifest and the segments it names. A merge killed mid-commit next
58		// to the chain is repaired or swept first.
59		sweepMergeDebris(backupDir)
60		binfo, err := os.Stat(backupDir)
61		if err != nil {
62			return nil, errBadBackup
63		}
64		if !binfo.IsDir() {
65			return nil, errBadBackup
66		}
67	
68		// When incremental rings extend the head artifact, the whole chain is
69		// validated up front (missing rings, broken links, discontinuous
70		// watermarks, truncation, checksum failures and unknown versions reject
71		// the entire directory); a head-only artifact keeps its original path.
72		hasRings, err := dirHasRings(backupDir)
73		if err != nil {
74			return nil, err
75		}
76		var chain artifactInfo
77		var manifest manifestInfo
78		if hasRings {
79			chain, err = validateBackupChain(backupDir)
80			if err != nil {
81				return nil, err
82			}
83			manifest = chain.head
84		} else {
85			manifest, err = loadBackupManifest(backupDir)
86			if err != nil {
87				// Content defects already wrap fs.ErrInvalid; an underlying read
88				// failure passes through unchanged.
89				return nil, err
90			}
91			if err := verifyBackupFileSet(backupDir, manifest.segments); err != nil {
92				return nil, err
93			}
94		}
95	
96		// The target must be absent or an empty directory.
97		if err := checkRestoreTarget(targetDir); err != nil {
98			return nil, err
99		}
100	
101		// Build the complete store in a temporary sibling so a kill never exposes
102		// a half-installed target. The sibling lives next to the target so the
103		// final rename is atomic on one filesystem.
104		parent := filepath.Dir(targetDir)
105		if err := os.MkdirAll(parent, 0o700); err != nil {
106			return nil, err
107		}
108		stage, err := os.MkdirTemp(parent, filepath.Base(targetDir)+".restore-*")
109		if err != nil {
110			return nil, err
111		}
112		installed := false
113		defer func() {
114			if !installed {
115				_ = os.RemoveAll(stage)
116			}
117		}()
118	
119		if hasRings {
120			err = buildChainRestoredStore(stage, backupDir, chain)
121		} else {
122			err = buildRestoredStore(stage, backupDir, manifest)
123		}
124		if err != nil {
125			// Artifact validation failures already wrap fs.ErrInvalid; a genuine
126			// write failure is reported as-is rather than mislabeled invalid.
127			return nil, err
128		}
129	
130		if err := installRestoreTarget(stage, targetDir); err != nil {
131			return nil, err
132		}
133		installed = true
134	
135		return Open(targetDir)
136	}
137	
138	// checkRestoreTarget accepts an absent path or an existing empty directory;
139	// anything else (a regular file, symlink, or non-empty directory) is invalid.
140	func checkRestoreTarget(target string) error {
141		info, err := os.Stat(target)
142		if err != nil {
143			if errors.Is(err, os.ErrNotExist) {
144				return nil
145			}
146			return err
147		}
148		if !info.IsDir() {
149			return errBadBackup
150		}
151		entries, err := os.ReadDir(target)
152		if err != nil {
153			return err
154		}
155		if len(entries) != 0 {
156			return errBadBackup
157		}
158		return nil
159	}
160	
161	// verifyBackupFileSet rejects any entry besides the manifest and exactly the
162	// dense segment set the manifest names, and rejects gaps or extras.
163	func verifyBackupFileSet(backupDir string, segs []manifestSegment) error {
164		entries, err := os.ReadDir(backupDir)
165		if err != nil {
166			return err
167		}
168		want := make(map[uint32]bool, len(segs))
169		for _, s := range segs {
170			if s.index != uint32(len(want)) {
171				return errBadBackup // dense, ordered 0..n-1
172			}
173			want[s.index] = true
174		}
175		got := make(map[uint32]bool, len(segs))
176		for _, e := range entries {
177			if e.IsDir() {
178				return errBadBackup // no staging or foreign directory in a valid artifact
179			}
180			name := e.Name()
181			if name == backupManifest || name == backupManifestTmp {
182				if name == backupManifestTmp {
183					return errBadBackup // an unfinished manifest means an unfinished export
184				}
185				continue
186			}
187			idx, ok := parseSegmentIndex(name)
188			if !ok {
189				return errBadBackup // foreign file
190			}
191			if !want[idx] {
192				return errBadBackup // extra segment
193			}
194			if got[idx] {
195				return errBadBackup
196			}
197			got[idx] = true
198		}
199		if len(got) != len(want) {
200			return errBadBackup // a named segment is missing
201		}
202		return nil
203	}
204	
205	// readFull reads exactly len(buf) bytes from r; a short read (a truncated
206	// artifact) is reported as errBadBackup rather than io.ErrUnexpectedEOF,
207	// while any other read failure passes through.
208	func readFull(r io.Reader, buf []byte) error {
209		if _, err := io.ReadFull(r, buf); err != nil {
210			if errors.Is(err, io.EOF) || errors.Is(err, io.ErrUnexpectedEOF) {
211				return errBadBackup
212			}
213			return err
214		}
215		return nil
216	}
217	
218	// loadBackupManifest reads and fully validates manifest.dat.
219	func loadBackupManifest(backupDir string) (manifestInfo, error) {
220		var zero manifestInfo
221		f, err := os.Open(filepath.Join(backupDir, backupManifest))
222		if err != nil {
223			// A missing manifest means the export never reached its commit point:
224			// the artifact is incomplete, not a transient I/O failure.
225			if errors.Is(err, os.ErrNotExist) {
226				return zero, errBadBackup
227			}
228			return zero, err
229		}
230		defer f.Close()
231	
232		r := bufio.NewReader(f)
233		head := make([]byte, backupManifestSize)
234		if err := readFull(r, head); err != nil {
235			return zero, err
236		}
237		h := crc32.NewIEEE()
238		h.Write(head)
239	
240		magic := binary.LittleEndian.Uint32(head[0:4])
241		version := binary.LittleEndian.Uint32(head[4:8])
242		if magic != backupMagic || version != backupVersion {
243			return zero, errBadBackup
244		}
245		info := manifestInfo{
246			watermark: binary.LittleEndian.Uint64(head[8:16]),
247			snaps:     binary.LittleEndian.Uint64(head[16:24]),
248			total:     binary.LittleEndian.Uint64(head[24:32]),
249		}
250		n := binary.LittleEndian.Uint32(head[32:36])
251		// Every segment carries at least one entry, so the segment count never
252		// exceeds the entry total; an empty artifact has n == 0 and total == 0.
253		// The absolute cap only guards the pre-allocation against a forged count;
254		// the record loop rejects an artifact that does not actually contain them.
255		if uint64(n) > info.total || n > backupMaxSegments {
256			return zero, errBadBackup
257		}
258	
259		rec := make([]byte, backupSegRecSize)
260		var cumulative uint64
261		info.segments = make([]manifestSegment, 0, n)
262		for i := uint32(0); i < n; i++ {
263			if err := readFull(r, rec); err != nil {
264				return zero, err
265			}
266			h.Write(rec)
267			s := manifestSegment{
268				index:      binary.LittleEndian.Uint32(rec[0:4]),
269				count:      binary.LittleEndian.Uint32(rec[4:8]),
270				cumulative: binary.LittleEndian.Uint64(rec[8:16]),
271				crc:        binary.LittleEndian.Uint32(rec[16:20]),
272			}
273			if s.index != i {
274				return zero, errBadBackup
275			}
276			cumulative += uint64(s.count)
277			if s.cumulative != cumulative || s.count == 0 {
278				return zero, errBadBackup
279			}
280			info.segments = append(info.segments, s)
281		}
282		if cumulative != info.total {
283			return zero, errBadBackup
284		}
285	
286		var crcb [crcSize]byte
287		if err := readFull(r, crcb[:]); err != nil {
288			return zero, err
289		}
290		if binary.LittleEndian.Uint32(crcb[:]) != h.Sum32() {
291			return zero, errBadBackup
292		}
293		info.crc = binary.LittleEndian.Uint32(crcb[:])
294		if _, err := r.ReadByte(); !errors.Is(err, io.EOF) {
295			return zero, errBadBackup // trailing bytes, or an underlying read error
296		}
297		return info, nil
298	}
299	
300	// buildRestoredStore streams every named segment into a fresh wal.log in the
301	// staging directory, validating each segment as it reads. The result is a WAL
302	// whose full replay reproduces the exported terminal state (one terminal
303	// frame per key, the same shape a compaction writes), followed by the snapshot
304	// count meta. Nothing is installed until this whole step succeeds.
305	func buildRestoredStore(stage, backupDir string, info manifestInfo) error {
306		wf, err := os.OpenFile(filepath.Join(stage, walName), os.O_RDWR|os.O_CREATE|os.O_EXCL, 0o600)
307		if err != nil {
308			return err
309		}
310		fail := func(err error) error {
311			wf.Close()
312			return err
313		}
314		l := &walWriter{f: wf, w: bufio.NewWriter(wf)}
315	
316		var seen uint64
317		var lastKey string
318		haveKeys := false
319	
320		for _, seg := range info.segments {
321			f, err := os.Open(filepath.Join(backupDir, segmentName(seg.index)))
322			if err != nil {
323				return fail(err)
324			}
325			r := bufio.NewReader(f)
326			hdr := make([]byte, backupSegHeaderSize)
327			if err := readFull(r, hdr); err != nil {
328				f.Close()
329				return fail(err)
330			}
331			h := crc32.NewIEEE()
332			h.Write(hdr)
333	
334			magic := binary.LittleEndian.Uint32(hdr[0:4])
335			version := binary.LittleEndian.Uint32(hdr[4:8])
336			watermark := binary.LittleEndian.Uint64(hdr[8:16])
337			snaps := binary.LittleEndian.Uint64(hdr[16:24])
338			index := binary.LittleEndian.Uint32(hdr[24:28])
339			count := binary.LittleEndian.Uint32(hdr[28:32])
340			cumulative := binary.LittleEndian.Uint64(hdr[32:40])
341			if magic != backupMagic || version != backupVersion ||
342				watermark != info.watermark || snaps != info.snaps ||
343				index != seg.index || count != seg.count || cumulative != seg.cumulative {
344				f.Close()
345				return fail(errBadBackup)
346			}
347	
348			ehdr := make([]byte, checkpointEntrySize)
349			for i := uint32(0); i < count; i++ {
350				if err := readFull(r, ehdr); err != nil {
351					f.Close()
352					return fail(err)
353				}
354				h.Write(ehdr)
355				flag := ehdr[0]
356				keyLen := binary.LittleEndian.Uint32(ehdr[1:5])
357				valLen := binary.LittleEndian.Uint32(ehdr[5:9])
358				seq := binary.LittleEndian.Uint64(ehdr[9:17])
359				if (flag != ckptFlagPut && flag != ckptFlagDelete) ||
360					keyLen == 0 || keyLen > maxRecord || valLen > maxRecord ||
361					(flag == ckptFlagDelete && valLen != 0) {
362					f.Close()
363					return fail(errBadBackup)
364				}
365				body := make([]byte, int(keyLen)+int(valLen))
366				if err := readFull(r, body); err != nil {
367					f.Close()
368					return fail(err)
369				}
370				h.Write(body)
371				key := string(body[:keyLen])
372				// Entries must be strictly ascending and unique across segments.
373				if haveKeys && key <= lastKey {
374					f.Close()
375					return fail(errBadBackup)
376				}
377				lastKey, haveKeys = key, true
378				value := body[keyLen:]
379				if flag == ckptFlagPut {
380					if err := l.encodeFrameSeq(opPutSeq, key, seq, value); err != nil {
381						f.Close()
382						return fail(err)
383					}
384				} else {
385					if err := l.encodeFrameSeq(opDeleteSeq, key, seq, nil); err != nil {
386						f.Close()
387						return fail(err)
388					}
389				}
390			}
391	
392			var crcb [crcSize]byte
393			if err := readFull(r, crcb[:]); err != nil {
394				f.Close()
395				return fail(err)
396			}
397			if binary.LittleEndian.Uint32(crcb[:]) != h.Sum32() ||
398				binary.LittleEndian.Uint32(crcb[:]) != seg.crc {
399				f.Close()
400				return fail(errBadBackup)
401			}
402			if _, err := r.ReadByte(); !errors.Is(err, io.EOF) {
403				f.Close()
404				return fail(errBadBackup)
405			}
406			f.Close()
407			seen += uint64(count)
408		}
409	
410		if seen != info.total {
411			return fail(errBadBackup)
412		}
413		if info.snaps > 0 {
414			var v [metaValueSize]byte
415			binary.LittleEndian.PutUint64(v[:], info.snaps)
416			if err := l.encodeFrame(opMeta, "", v[:]); err != nil {
417				return fail(err)
418			}
419		}
420		if err := l.w.Flush(); err != nil {
421			return fail(err)
422		}
423		if err := wf.Sync(); err != nil {
424			return fail(err)
425		}
426		if err := wf.Close(); err != nil {
427			return err
428		}
429		return syncDirectory(stage)
430	}
431	
432	// installRestoreTarget puts the fully built staging store onto target. The
433	// target is absent or empty: when it exists as an empty directory it is
434	// removed first, so the rename lands on no existing entry. A crash in between
435	// leaves either an empty/absent target or the complete store, never a partial
436	// one.
437	func installRestoreTarget(stage, target string) error {
438		if info, err := os.Stat(target); err == nil && info.IsDir() {
439			if err := os.Remove(target); err != nil {
440				return err
441			}
442			if err := syncDirectory(filepath.Dir(target)); err != nil {
443				return err
444			}
445		}
446		if err := os.Rename(stage, target); err != nil {
447			return err
448		}
449		return syncDirectory(filepath.Dir(target))
450	}
451	
452	// sweepRestoreDebris removes a half-built temporary restore directory left
453	// next to dir by a kill during Restore. It only ever removes the specific
454	// sibling names Restore creates.
455	func sweepRestoreDebris(dir string) {
456		parent := filepath.Dir(dir)
457		base := filepath.Base(dir)
458		entries, err := os.ReadDir(parent)
459		if err != nil {
460			return
461		}
462		fixed := base + ".restore.tmp"
463		for _, e := range entries {
464			name := e.Name()
465			if !e.IsDir() {
466				continue
467			}
468			if name == fixed || isRestoreTempName(name, base) {
469				_ = os.RemoveAll(filepath.Join(parent, name))
470			}
471		}
472		_ = syncDirectory(parent)
473	}
474	
475	// isRestoreTempName matches MkdirTemp's "<base>.restore-<random>" directories.
476	func isRestoreTempName(name, base string) bool {
477		prefix := base + ".restore-"
478		return len(name) > len(prefix) && name[:len(prefix)] == prefix
479	}
480	
481	// openBackupSweep cleans incomplete-backup debris found when opening a
482	// directory that was used as a backup output: a staging directory or manifest
483	// temp is always debris, and finished segments are debris only when the
484	// manifest that completes the artifact is absent. A complete artifact is left
485	// untouched.
486	func openBackupSweep(dir string) error {
487		if err := sweepBackupDebris(dir); err != nil {
488			return err
489		}
490		if _, err := os.Stat(filepath.Join(dir, backupManifest)); err == nil {
491			return nil // complete artifact; leave it in place
492		}
493		entries, err := os.ReadDir(dir)
494		if err != nil {
495			return err
496		}
497		var names []string
498		for _, e := range entries {
499			if e.IsDir() {
500				continue
501			}
502			if isBackupSegmentName(e.Name()) {
503				names = append(names, e.Name())
504			}
505			if _, ok := parseRingIndex(e.Name()); ok {
506				names = append(names, e.Name())
507			}
508		}
509		sort.Strings(names)
510		for _, name := range names {
511			if err := os.Remove(filepath.Join(dir, name)); err != nil &&
512				!errors.Is(err, os.ErrNotExist) {
513				return err
514			}
515		}
516		if len(names) > 0 {
517			return syncDirectory(dir)
518		}
519		return nil
520	}
521

