	// reshape one chain directory concurrently. Independent of mu: held across
	// the verification's disk I/O, never blocking commits or reads.
	s.backupMu.Lock()
	defer s.backupMu.Unlock()
	if s.closed.Load() {
		return errStoreClosed
	}
	if chainDir == "" {
		return errBadBackup
	}
	// Coordinate with every other operation on this chain directory, in this
	// process or another: only the lease holder inspects and reshapes the
	// chain. A live holder fails the whole verification; a killed holder's
	// lease is reclaimed.
	lease, err := acquireChainLease(chainDir)
	if err != nil {
		return err
	}
	defer lease.release()

	// Repair or clear debris from a merge or a verification killed mid-commit
	// before inspecting the chain, exactly as the next backup or open would.
	sweepChainDebris(chainDir)

	info, err := os.Stat(chainDir)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return errBadBackup
		}
		return err
	}
	if !info.IsDir() {
		return errBadBackup
	}
	// Staging debris from an export (full or incremental) killed mid-run is
	// never part of a finished chain and is swept before inspection; a
	// manifest temp is pure debris as well. Any other foreign entry below
	// rejects the whole directory.
	if err := sweepBackupDebris(chainDir); err != nil {
		return err
	}

	// Inspect the layout first: the chain must hold exactly the manifest, the
	// dense head segments and a dense, gap-free ring set. Any foreign file
	// rejects the whole chain before a single byte of it is trusted.
	layout, err := inspectChainLayout(chainDir)
	if err != nil {
		return err
	}

	// Deep-validate the head first, streaming it. The head is the irreducible
	// prefix: a damaged head cannot be downgraded around, so it rejects the
	// whole chain and leaves it untouched.
	head, err := loadBackupManifest(chainDir)
	if err != nil {
		return err
	}
	if err := checkHeadLayout(chainDir, layout, head); err != nil {
		return err
	}
	if err := streamHeadSegments(chainDir, head, nil); err != nil {
		return err
	}

	// Walk the rings in order, streaming and fully validating each one against
	// its predecessor. The first defect fixes the intact prefix: everything
	// from that ring on is isolated and the chain downgraded to the prefix.
	good := uint32(0)
	prevWM := head.watermark
	prevSnaps := head.snaps
	prevLink := head.crc
	for idx := uint32(1); idx <= layout.ringCount; idx++ {
		f, oerr := os.Open(filepath.Join(chainDir, ringName(idx)))
		if oerr != nil {
			return oerr
		}
		_, serr := scanRing(f, ringExpect{
			index:    idx,
			prevLink: prevLink,
			startWM:  prevWM,
		}, nil)
		f.Close()
		if serr != nil {
			// Defect at ring idx: keep rings 1..idx-1 as the intact prefix.
			return s.downgradeChain(chainDir, layout, good)
		}
		// scanRing validated the ring structurally; record its tip for the
		// next ring without re-streaming, by reading just its summary fields.
		sum, err := readRingSummary(filepath.Join(chainDir, ringName(idx)))
		if err != nil {
			return err
		}
		if sum.snaps < prevSnaps {
			return s.downgradeChain(chainDir, layout, good)
		}
		good = idx
		prevWM = sum.endWM
		prevSnaps = sum.snaps
		prevLink = sum.fileCRC
	}

	// The whole chain is intact.
	return nil
}

// chainLayout is the file inventory of a chain directory, after rejecting
// every entry that is not part of a finished chain.
type chainLayout struct {
	ringCount uint32          // number of dense rings present, 1..ringCount
	entries   []os.DirEntry    // every accepted entry (manifest, segments, rings)
}

// inspectChainLayout lists chainDir and accepts only the head manifest,
// well-formed segment file names and well-formed ring file names. Any
// directory, temp or foreign name rejects the whole chain. The ring set must
// be exactly the dense sequence 1..n: a gap or a duplicate is a layout
// defect. The segment names are only shape-checked here; their agreement
// with the manifest is checked once the manifest is loaded.
func inspectChainLayout(chainDir string) (chainLayout, error) {
	var zero chainLayout
	entries, err := os.ReadDir(chainDir)
	if err != nil {
		return zero, err
	}
	rings := make(map[uint32]bool)
	var maxRing uint32
	out := make([]os.DirEntry, 0, len(entries))
	for _, e := range entries {
		name := e.Name()
		if e.IsDir() {
			return zero, errBadBackup // no staging or foreign directory in a chain
		}
		switch {
		case name == backupManifest:
		case name == backupManifestTmp:
			return zero, errBadBackup // an unfinished manifest means unfinished work
		default:
			if _, ok := parseSegmentIndex(name); ok {
				break
			}
			if idx, ok := parseRingIndex(name); ok {
				if rings[idx] {
					return zero, errBadBackup
				}
				rings[idx] = true
				if idx > maxRing {
					maxRing = idx
				}
				break
			}
			return zero, errBadBackup // foreign file
		}
		out = append(out, e)
	}
	for idx := uint32(1); idx <= maxRing; idx++ {
		if !rings[idx] {
			return zero, errBadBackup // a gap in the dense ring sequence
		}
	}
	return chainLayout{ringCount: maxRing, entries: out}, nil
}

// checkHeadLayout verifies the head segments on disk are exactly the dense
// set the manifest names — none missing, none extra.
func checkHeadLayout(chainDir string, layout chainLayout, head manifestInfo) error {
	want := make(map[uint32]bool, len(head.segments))
	for _, seg := range head.segments {
		if seg.index != uint32(len(want)) {
			return errBadBackup // dense, ordered 0..n-1
		}
		want[seg.index] = true
	}
	got := make(map[uint32]bool, len(want))
	for _, e := range layout.entries {
		name := e.Name()
		if name == backupManifest {
			continue
		}
		if idx, ok := parseRingIndex(name); ok {
			_ = idx
			continue
		}
		idx, ok := parseSegmentIndex(name)
		if !ok {
			return errBadBackup
		}
		if !want[idx] || got[idx] {
			return errBadBackup // an extra segment, or a duplicate
		}
		got[idx] = true
	}
	if len(got) != len(want) {
		return errBadBackup // a manifest-named segment is absent
	}
	return nil
}

// readRingSummary reads only the fixed header and footer fields of a ring
// already known to be structurally valid, returning its linkage summary. It
// is the bounded-memory counterpart of scanRing for the verify walk, which
// has already streamed and checksummed the ring once.
func readRingSummary(path string) (ringSummary, error) {
	var zero ringSummary
	f, err := os.Open(path)
	if err != nil {
		return zero, err
	}
	defer f.Close()
	head := make([]byte, incrRingHeaderSize)
	if _, err := readFullAt(f, head, 0); err != nil {
		return zero, err
	}
	index := binary.LittleEndian.Uint32(head[8:12])
	endWM := binary.LittleEndian.Uint64(head[24:32])
	snaps := binary.LittleEndian.Uint64(head[32:40])
	segCount := binary.LittleEndian.Uint32(head[40:44])

	size, err := f.Seek(0, 2)
	if err != nil {
		return zero, err
	}
	// Footer plus the terminal whole-file CRC sit at the tail of the file.
	tail := make([]byte, incrFooterSize+crcSize)
	if _, err := readFullAt(f, tail, size-int64(len(tail))); err != nil {
		return zero, err
	}
	total := binary.LittleEndian.Uint64(tail[0:8])
	fileCRC := binary.LittleEndian.Uint32(tail[incrFooterSize : incrFooterSize+crcSize])
	return ringSummary{
		index:    index,
		endWM:    endWM,
		snaps:    snaps,
		total:    total,
		fileCRC:  fileCRC,
		segCount: segCount,
	}, nil
}

// downgradeChain isolates rings good+1..end of the chain in chainDir into a
// diagnostic sibling and leaves the intact prefix (the head plus rings
// 1..good) at chainDir. It returns nil on success; on any failure to commit
// the downgrade it returns that failure and the chain directory stays the
// intact-or-original whole chain. The isolated artifacts are preserved
// byte-for-byte.
//
// The whole switch is staged as siblings and committed by directory renames,
// so a kill at any instant leaves either the original chain or the complete
// downgraded chain.
func (s *Store) downgradeChain(chainDir string, layout chainLayout, good uint32) error {
	parent := filepath.Dir(chainDir)
	base := filepath.Base(chainDir)

	// Stage the intact prefix in a sibling directory: hard links keep the
	// artifacts byte-identical without copying their bytes.
	stage, err := os.MkdirTemp(parent, base+verifyStagePrefix)
	if err != nil {
		return err
	}
	committed := false
	defer func() {
		if !committed {
			_ = os.RemoveAll(stage)
		}
	}()
	for _, e := range layout.entries {
		name := e.Name()
		if name == backupManifest {
			if err := linkFile(chainDir, stage, name); err != nil {
				return err
			}
			continue
		}
		if idx, ok := parseRingIndex(name); ok {
			if idx <= good {
				if err := linkFile(chainDir, stage, name); err != nil {
					return err
				}
			}
			continue
		}
		if _, ok := parseSegmentIndex(name); ok {
			if err := linkFile(chainDir, stage, name); err != nil {
				return err
			}
		}
	}
	if err := syncDirectory(stage); err != nil {
		return err
	}
	// The staged prefix must itself validate as one whole chain.
	if _, err := validateBackupChain(stage); err != nil {
		return err
	}

	// Commit by moving the old chain aside to a trash sibling and the staged
	// prefix onto the chain path. A kill before the first rename leaves the
	// original chain; a kill between the renames leaves the whole old chain in
	// the trash sibling and is repaired by moving it back on the next sweep.
	trash, err := os.MkdirTemp(parent, base+verifyTrashPrefix)
	if err != nil {
		return err
	}
	if err := os.Remove(trash); err != nil {
		return err
	}
	if err := os.Rename(chainDir, trash); err != nil {
		return err
	}
	if err := os.Rename(stage, chainDir); err != nil {
		if rb := os.Rename(trash, chainDir); rb == nil {
			_ = syncDirectory(parent)
		}
		return err
	}
	committed = true
	if err := syncDirectory(parent); err != nil {
		return err
	}

	// The downgraded chain is now live at chainDir. Preserve the isolated
	// suffix (rings good+1..end) from the old chain in the trash into a fresh
	// diagnostic sibling, byte for byte. Best effort never to destroy the
	// evidence: if it cannot be published, leave it in the trash sibling so a
	// later sweep repair keeps both; the live chain is already the healed one.
	if good < layout.ringCount {
		diag, derr := publishDiagnostics(parent, base, trash, good, layout.ringCount)
		if derr != nil {
			return derr
		}
		_ = diag
	}
	if err := os.RemoveAll(trash); err != nil {
		return err
	}
	return syncDirectory(parent)
}

// publishDiagnostics creates the diagnostic sibling directory next to the
// chain and hard-links the isolated rings (indices good+1..end) from trash —
// the retired original chain — into it, preserving their bytes exactly. It
// returns the diagnostic directory path.
func publishDiagnostics(parent, base, trash string, good, end uint32) (string, error) {
	diag, err := os.MkdirTemp(parent, base+verifyDiagPrefix)
	if err != nil {
		return "", err
	}
	kept := false
	for idx := good + 1; idx <= end; idx++ {
		name := ringName(idx)
		if err := os.Link(filepath.Join(trash, name), filepath.Join(diag, name)); err != nil {
			if errors.Is(err, os.ErrNotExist) {
				continue
			}
			_ = os.RemoveAll(diag)
			return "", err
		}
		kept = true
	}
	if !kept {
		// Nothing to preserve; drop the empty diagnostic directory.
		_ = os.Remove(diag)
		return "", nil
	}
	if err := syncDirectory(diag); err != nil {
		_ = os.RemoveAll(diag)
		return "", err
	}
	return diag, nil
}

// linkFile hard-links name from src directory into dst directory. A hard link
// shares the bytes, so the staged artifact is byte-identical to the source.
func linkFile(srcDir, dstDir, name string) error {
	return os.Link(filepath.Join(srcDir, name), filepath.Join(dstDir, name))
}

// readFullAt reads exactly len(buf) bytes at off from f, mapping a short read
// (a truncated file) to errBadBackup and passing other failures through.
func readFullAt(f *os.File, buf []byte, off int64) (int, error) {
	n, err := f.ReadAt(buf, off)
	if err != nil && !errors.Is(err, errShortReadSentinel) {
		if errors.Is(err, errBadBackup) {
			return n, err
		}
	}
	if n == len(buf) {
		return n, nil
	}
	return n, errBadBackup
}

