func TestVerifyChainHeadCorruptRejects(t *testing.T) {
	newChain := func(t *testing.T) (string, []fileDigest) {
		s := openStore(t, tempDir(t))
		if err := s.Put("k", []byte("v")); err != nil {
			t.Fatal(err)
