			t.Fatal(err)
		}
		if err := s.Put("k", []byte("v2")); err != nil {
			t.Fatal(err)
		}
		if err := s.BackupIncremental(chain); err != nil {
			t.Fatal(err)
		}
		return chain, digestDir(t, chain)
	}

	t.Run("corrupt segment", func(t *testing.T) {
		s := openStore(t, tempDir(t))
		chain, before := newChain(t)
		p := filepath.Join(chain, segmentName(0))
		data, err := os.ReadFile(p)
		if err != nil {
			t.Fatal(err)
		}
		data[len(data)/2] ^= 0xff
		if err := os.WriteFile(p, data, 0o600); err != nil {
			t.Fatal(err)
		}
		if err := s.VerifyChain(chain); !errors.Is(err, fs.ErrInvalid) {
			t.Fatalf("verify corrupt head = %v, want fs.ErrInvalid", err)
		}
		// The rejection overwrote the damaged file itself, but the directory's
		// membership is otherwise unchanged: manifest, segment and ring all
		// still present, no diagnostics or staging.
		after := digestDir(t, chain)
		after[0].data, after[0].size = before[0].data, before[0].size
		if len(after) != len(before) {
			t.Fatalf("file set changed: %v vs %v", namesOf(after), namesOf(before))
		}
		if len(diagDirs(t, chain)) != 0 {
			t.Fatal("head rejection created a diagnostic directory")
		}
	})

	t.Run("corrupt manifest", func(t *testing.T) {
		s := openStore(t, tempDir(t))
		chain, before := newChain(t)
		p := filepath.Join(chain, backupManifest)
		data, err := os.ReadFile(p)
		if err != nil {
			t.Fatal(err)
		}
		data[10] ^= 0xff
		if err := os.WriteFile(p, data, 0o600); err != nil {
			t.Fatal(err)
		}
		if err := s.VerifyChain(chain); !errors.Is(err, fs.ErrInvalid) {
			t.Fatalf("verify corrupt manifest = %v, want fs.ErrInvalid", err)
		}
		after := digestDir(t, chain)
		if len(after) != len(before) {
			t.Fatalf("file set changed: %v vs %v", namesOf(after), namesOf(before))
		}
		if len(diagDirs(t, chain)) != 0 {
			t.Fatal("head rejection created a diagnostic directory")
		}
	})
}

