	out := make([]string, 0, len(ds))
	for _, d := range ds {
		out = append(out, d.name)
	}
	sort.Strings(out)
	return out
}

func namesOfMap(m map[string][]byte) []string {
	out := make([]string, 0, len(m))
	for name := range m {
		out = append(out, name)
	}
	sort.Strings(out)
	return out
}

