// chainLayout is the accepted ring inventory of a chain directory. Segment
// and manifest names are shape-accepted during the listing but not retained:
// the intact-chain path streams without holding every directory entry, and a
// downgrade re-lists the directory when it actually stages files.
type chainLayout struct {
	ringCount uint32          // highest ring index present (0 = head only)
	present   map[uint32]bool // ring indices that have a file
}

// inspectChainLayout lists chainDir and accepts only the head manifest,
// well-formed segment file names and well-formed ring file names. Any
// directory, temp or foreign name rejects the whole chain. The ring set may
// have a gap (a missing ring is one form of a damaged ring): the walk treats
// the first missing index as the downgrade point. Segment names are only
// shape-checked here; their agreement with the manifest is checked once the
// manifest is loaded.
func inspectChainLayout(chainDir string) (chainLayout, error) {
	var zero chainLayout
	entries, err := os.ReadDir(chainDir)
	if err != nil {
		return zero, err
	}
	rings := make(map[uint32]bool)
	var maxRing uint32
	for _, e := range entries {
		name := e.Name()
		if e.IsDir() {
			return zero, errBadBackup // no staging or foreign directory in a chain
		}
		switch {
		case name == backupManifest, name == backupManifestTmp:
			if name == backupManifestTmp {
				return zero, errBadBackup // unfinished manifest means unfinished work
			}
		default:
			if _, ok := parseSegmentIndex(name); ok {
				break
			}
			if idx, ok := parseRingIndex(name); ok {
				rings[idx] = true
				if idx > maxRing {
					maxRing = idx
				}
				break
			}
			return zero, errBadBackup // foreign file
		}
	}
	return chainLayout{ringCount: maxRing, present: rings}, nil
}

